1	/**
2	 * 扩展行动库
3	 *
4	 * 涵盖：街头生存 / 经营 / 社交 / 学习 / 生活 / 投资 / 梦想实现
5	 * 参考：《北京浮生记》《大多数》《中国式家长》《这是我的战争》《Stardew Valley》
6	 *
7	 * 用法：getAvailableActions() 末尾会调用 addExtraActions() 把这些行动合并进去
8	 */
9	
10	/** 街头阶段通用行动（不依赖地点） */
11	function addStreetExtras(state, actions) {
12	  // === 街头生存类（任何街头地点都行） ===
13	  actions.push({
14	    id: "scavenge_trash",
15	    name: "🗑️ 翻垃圾桶找废品",
16	    desc: "在巷子里翻垃圾桶找瓶瓶罐罐卖钱。脏但能赚点零花钱。",
17	    icon: "🗑️",
18	    apCost: 20,
19	    payEstimate: "2~9",
20	    handler: () => {
21	      const earned = 2 + Math.floor(Math.random() * 8);
22	      const st = StateManager.getState();
23	      st.resources.cash += earned;
24	      st.needs.hygiene = Math.max(0, st.needs.hygiene - 5);
25	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 5);
26	      st.resources.totalEarned += earned;
27	      StateManager.addMessage(
28	        `🗑️ 翻了半天垃圾桶，捡到 ¥${earned}，脏兮兮的。`,
29	        "success",
30	      );
31	      consumeAP(20);
32	    },
33	  });
34	
35	  actions.push({
36	    id: "busking",
37	    name: "🎤 街头卖唱",
38	    desc: "在地铁口或天桥上唱歌赚打赏。需要胆子大。",
39	    icon: "🎤",
40	    apCost: 20,
41	    payEstimate: "5~25",
42	    handler: () => {
43	      const st = StateManager.getState();
44	      const skill = st.player.mental; // 心智影响成功率
45	      const earned = Math.floor(5 + Math.random() * 20 + (skill - 25) * 0.3);
46	      st.resources.cash += earned;
47	      st.resources.totalEarned += earned;
48	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 10);
49	      st.status.fame = Math.min(100, st.status.fame + 1);
50	      if (Math.random() < 0.2) {
51	        st.needs.happiness = Math.max(0, st.needs.happiness - 5);
52	        StateManager.addMessage(
53	          `🎤 唱了半天，城管赶人+路人嫌弃，赚到 ¥${earned}。`,
54	          "warning",
55	        );
56	      } else {
57	        st.needs.happiness = Math.min(100, st.needs.happiness + 8);
58	        StateManager.addMessage(
59	          `🎤 卖唱结束，收获 ¥${earned} 打赏！心情好。`,
60	          "success",
61	        );
62	      }
63	      consumeAP(20);
64	    },
65	  });
66	
67	  actions.push({
68	    id: "beg",
69	    name: "🙏 街头乞讨",
70	    desc: "放下尊严，跪地要饭。（有尊严损失）",
71	    icon: "🙏",
72	    apCost: 20,
73	    payEstimate: "1~5",
74	    handler: () => {
75	      const st = StateManager.getState();
76	      const earned = 1 + Math.floor(Math.random() * 5);
77	      st.resources.cash += earned;
78	      st.resources.totalEarned += earned;
79	      st.needs.happiness = Math.max(0, st.needs.happiness - 12);
80	      st.status.fame = Math.max(0, st.status.fame - 2);
81	      StateManager.addMessage(
82	        `🙏 跪了半小时，收到 ¥${earned}。心里五味杂陈。`,
83	        "warning",
84	      );
85	      consumeAP(20);
86	    },
87	  });
88	
89	  actions.push({
90	    id: "play_dice",
91	    name: "🎲 路边赌骰子",
92	    desc: "和地摊小贩玩骰子，押 50 赢了翻倍，输了打水漂。",
93	    icon: "🎲",
94	    costEstimate: 50,
95	    apCost: 20,
96	    payEstimate: "0或100",
97	    handler: () => {
98	      const st = StateManager.getState();
99	      if (st.resources.cash < 50) {
100	        StateManager.addMessage("🎲 押不起 50 块。", "warning");
101	        return;
102	      }
103	      st.resources.cash -= 50;
104	      if (Math.random() < 0.45) {
105	        st.resources.cash += 100;
106	        st.resources.totalEarned += 50;
107	        st.needs.happiness = Math.min(100, st.needs.happiness + 10);
108	        StateManager.addMessage("🎲 赢了！100 块到手！", "success");
109	      } else {
110	        st.needs.happiness = Math.max(0, st.needs.happiness - 8);
111	        StateManager.addMessage("🎲 输了...50 块没了。", "danger");
112	      }
113	      consumeAP(20);
114	    },
115	  });
116	
117	  // === 社交 / 家庭类 ===
118	  actions.push({
119	    id: "call_home",
120	    name: "📞 给家里打电话",
121	    desc: "用公用电话给爸妈报平安，听听唠叨。",
122	    icon: "📞",
123	    costEstimate: 2,
124	    handler: () => {
125	      const st = StateManager.getState();
126	      if (st.resources.cash < 2) {
127	        StateManager.addMessage("📞 电话费都付不起...", "warning");
128	        return;
129	      }
130	      st.resources.cash -= 2;
131	      st.needs.happiness = Math.min(100, st.needs.happiness + 15);
132	      st.needs.hunger = Math.max(0, st.needs.hunger - 3);
133	      if (Math.random() < 0.3) {
134	        st.resources.cash += 200; // 爸妈塞的钱
135	        StateManager.addMessage(
136	          "📞 妈妈在电话里哭了，让你注意身体，转了 200 块。",
137	          "success",
138	        );
139	        st.resources.totalEarned += 200;
140	      } else {
141	        StateManager.addMessage(
142	          "📞 和爸妈聊了 10 分钟，心情好多了。",
143	          "success",
144	        );
145	      }
146	      consumeAP(20);
147	    },
148	  });
149	
150	  actions.push({
151	    id: "remit_home",
152	    name: "💌 给家里汇款",
153	    desc: "把一部分钱寄回老家。",
154	    icon: "💌",
155	    costEstimate: "200~1000",
156	    handler: () => {
157	      showRemitModal();
158	    },
159	  });
160	
161	  actions.push({
162	    id: "internet_bar",
163	    name: "💻 网吧上网",
164	    desc: "花 5 块在网吧上 2 小时网，可以查资料、刷视频、玩游戏。",
165	    icon: "💻",
166	    costEstimate: 5,
167	    apCost: 20,
168	    payEstimate: "智力+0.3, 随机技能XP",
169	    disabled: state.resources.cash < 5,
170	    reqFail: state.resources.cash < 5 ? "现金不足" : null,
171	    handler: () => {
172	      const st = StateManager.getState();
173	      if (st.resources.cash < 5) {
174	        StateManager.addMessage("💻 5 块都掏不出来。", "warning");
175	        return;
176	      }
177	      st.resources.cash -= 5;
178	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 8);
179	      st.player.intelligence = Math.min(100, st.player.intelligence + 0.3);
180	      const skills = ["english", "coding", "accounting"];
181	      const sk = skills[Math.floor(Math.random() * skills.length)];
182	      st.skills[sk].xp += 5 + Math.floor(Math.random() * 10);
183	      st.needs.happiness = Math.min(100, st.needs.happiness + 5);
184	      StateManager.addMessage(
185	        "💻 在网吧待了 2 小时，智力+，还有点收获。",
186	        "info",
187	      );
188	      consumeAP(20);
189	    },
190	  });
191	
192	  actions.push({
193	    id: "salon_chat",
194	    name: "💈 路边理发店聊天",
195	    desc: "花 10 块剪个头发，顺便听听老板吹牛。需要敏捷≥18才能帮上忙。",
196	    icon: "💈",
197	    costEstimate: 10,
198	    apCost: 20,
199	    payEstimate: "心情+10",
200	    disabled: state.player.agility < 18 || state.resources.cash < 10,
201	    reqFail:
202	      state.player.agility < 18
203	        ? "需敏捷≥18"
204	        : state.resources.cash < 10
205	          ? "现金不足"
206	          : null,
207	    handler: () => {
208	      const st = StateManager.getState();
209	      if (st.resources.cash < 10) {
210	        StateManager.addMessage("💈 剪不起头。", "warning");
211	        return;
212	      }
213	      st.resources.cash -= 10;
214	      st.needs.hygiene = Math.min(100, st.needs.hygiene + 25);
215	      st.needs.happiness = Math.min(100, st.needs.happiness + 10);
216	      st.status.fame = Math.min(100, st.status.fame + 1);
217	      StateManager.addMessage(
218	        "💈 剪了个利索的短发！清爽多了，运气好像也好了点。",
219	        "success",
220	      );
221	      consumeAP(20);
222	    },
223	  });
224	
225	  // === 学习类 ===
226	  actions.push({
227	    id: "self_study",
228	    name: "📖 图书馆自习",
229	    desc: "去图书馆（商业区旁）安静看书。",
230	    icon: "📖",
231	    apCost: 20,
232	    payEstimate: "技能XP+30",
233	    handler: () => {
234	      const st = StateManager.getState();
235	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 10);
236	      const skills = Object.keys(st.skills);
237	      const key = skills[Math.floor(Math.random() * skills.length)];
238	      st.skills[key].xp += 30 + Math.floor(Math.random() * 20);
239	      st.player.intelligence = Math.min(100, st.player.intelligence + 0.2);
240	      StateManager.addMessage(
241	        `📖 在图书馆泡了一下午，${key} 技能经验大涨！`,
242	        "success",
243	      );
244	      consumeAP(20);
245	    },
246	  });
247	
248	  actions.push({
249	    id: "night_school",
250	    name: "🌃 上夜校",
251	    desc: "晚上上夜校，提升智力+相关技能。需要 ¥50 学费，智力≥25。",
252	    icon: "🌃",
253	    costEstimate: 50,
254	    apCost: 20,
255	    payEstimate: "智力+1, 技能+",
256	    disabled: state.player.intelligence < 25 || state.resources.cash < 50,
257	    reqFail:
258	      state.player.intelligence < 25
259	        ? "需智力≥25"
260	        : state.resources.cash < 50
261	          ? "现金不足"
262	          : null,
263	    handler: () => {
264	      const st = StateManager.getState();
265	      if (st.resources.cash < 50) {
266	        StateManager.addMessage("🌃 学费 50 块都交不起。", "warning");
267	        return;
268	      }
269	      st.resources.cash -= 50;
270	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 15);
271	      st.player.intelligence = Math.min(100, st.player.intelligence + 1);
272	      st.skills.english.xp += 30;
273	      st.skills.coding.xp += 30;
274	      st.skills.accounting.xp += 20;
275	      StateManager.addMessage(
276	        "🌃 夜校下课！智力+1，英语/编程/会计都涨了。累趴。",
277	        "success",
278	      );
279	      consumeAP(20);
280	    },
281	  });
282	
283	  // === 生活类 ===
284	  actions.push({
285	    id: "gym",
286	    name: "🏋️ 办健身卡锻炼",
287	    desc: "去健身房办月卡，提升体质和敏捷。",
288	    icon: "🏋️",
289	    costEstimate: 200,
290	    apCost: 20,
291	    payEstimate: "体质+1, 敏捷+0.5",
292	    handler: () => {
293	      const st = StateManager.getState();
294	      if (st.resources.cash < 200) {
295	        StateManager.addMessage("🏋️ 月卡 200 块都办不起。", "warning");
296	        return;
297	      }
298	      st.resources.cash -= 200;
299	      st.player.physique = Math.min(100, st.player.physique + 1);
300	      st.player.agility = Math.min(100, st.player.agility + 0.5);
301	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 15);
302	      st.needs.happiness = Math.min(100, st.needs.happiness + 6);
303	      st.status.health = Math.min(100, st.status.health + 3);
304	      StateManager.addMessage(
305	        "🏋️ 在健身房撸铁 2 小时！体质+1，敏捷+0.5，累了但快乐。",
306	        "success",
307	      );
308	      consumeAP(20);
309	    },
310	  });
311	
312	  actions.push({
313	    id: "movie",
314	    name: "🎬 看场电影",
315	    desc: "去影院看场电影放松一下。",
316	    icon: "🎬",
317	    costEstimate: 35,
318	    apCost: 20,
319	    payEstimate: "心情+18",
320	    handler: () => {
321	      const st = StateManager.getState();
322	      if (st.resources.cash < 35) {
323	        StateManager.addMessage("🎬 35 块都掏不出来。", "warning");
324	        return;
325	      }
326	      st.resources.cash -= 35;
327	      st.needs.fatigue = Math.max(0, st.needs.fatigue - 8);
328	      st.needs.happiness = Math.min(100, st.needs.happiness + 18);
329	      st.status.fame = Math.min(100, st.status.fame + 0.5);
330	      StateManager.addMessage(
331	        "🎬 看了一部催泪电影，感动得稀里哗啦。心情大好！",
332	        "success",
333	      );
334	      consumeAP(20);
335	    },
336	  });
337	
338	  actions.push({
339	    id: "ktv",
340	    name: "🎤 KTV 唱歌",
341	    desc: "约朋友去 KTV 吼两小时。",
342	    icon: "🎤",
343	    costEstimate: 80,
344	    apCost: 20,
345	    payEstimate: "心情+25, 人缘+",
346	    handler: () => {
347	      const st = StateManager.getState();
348	      if (st.resources.cash < 80) {
349	        StateManager.addMessage("🎤 80 块都凑不齐。", "warning");
350	        return;
351	      }
352	      st.resources.cash -= 80;
353	      st.needs.happiness = Math.min(100, st.needs.happiness + 25);
354	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 5);
355	      st.needs.hunger = Math.max(0, st.needs.hunger - 8);
356	      st.status.fame = Math.min(100, st.status.fame + 1);
357	      StateManager.addMessage(
358	        "🎤 吼了 2 小时，嗓子都哑了！心情+25。",
359	        "success",
360	      );
361	      consumeAP(20);
362	    },
363	  });
364	
365	  actions.push({
366	    id: "pharmacy",
367	    name: "💊 买药/买营养品",
368	    desc: "去药房买维生素、补品等。需要 ¥30~80。",
369	    icon: "💊",
370	    costEstimate: 30,
371	    apCost: 20,
372	    payEstimate: "健康+5",
373	    handler: () => {
374	      const st = StateManager.getState();
375	      if (st.resources.cash < 30) {
376	        StateManager.addMessage("💊 30 块都掏不出来。", "warning");
377	        return;
378	      }
379	      st.resources.cash -= 30;
380	      st.status.health = Math.min(100, st.status.health + 5);
381	      st.player.physique = Math.min(100, st.player.physique + 0.3);
382	      StateManager.addMessage(
383	        "💊 买了瓶复合维生素，感觉自己又行了。健康+5。",
384	        "success",
385	      );
386	      consumeAP(20);
387	    },
388	  });
389	
390	  actions.push({
391	    id: "supermarket",
392	    name: "🛒 去超市采购",
393	    desc: "去超市买点吃的用的。需要 ¥30~60。",
394	    icon: "🛒",
395	    costEstimate: 30,
396	    apCost: 20,
397	    payEstimate: "饥饱+30, 卫生+",
398	    handler: () => {
399	      const st = StateManager.getState();
400	      if (st.resources.cash < 30) {
401	        StateManager.addMessage("🛒 30 块都掏不出来。", "warning");
402	        return;
403	      }
404	      st.resources.cash -= 30;
405	      st.needs.hunger = Math.min(100, st.needs.hunger + 30);
406	      st.needs.hygiene = Math.min(100, st.needs.hygiene + 15);
407	      st.needs.happiness = Math.min(100, st.needs.happiness + 3);
408	      StateManager.addMessage(
409	        "🛒 超市采购了泡面、纸巾、零食。饥饱+30，卫生+15。",
410	        "success",
411	      );
412	      consumeAP(20);
413	    },
414	  });
415	
416	  actions.push({
417	    id: "clothing",
418	    name: "👕 买件新衣服",
419	    desc: "去服装店买件像样的衣服，提升卫生/心情/名气。",
420	    icon: "👕",
421	    costEstimate: 80,
422	    apCost: 20,
423	    payEstimate: "卫生+10, 名气+",
424	    handler: () => {
425	      const st = StateManager.getState();
426	      if (st.resources.cash < 80) {
427	        StateManager.addMessage("👕 80 块都掏不出来。", "warning");
428	        return;
429	      }
430	      st.resources.cash -= 80;
431	      st.needs.hygiene = Math.min(100, st.needs.hygiene + 10);
432	      st.needs.happiness = Math.min(100, st.needs.happiness + 8);
433	      st.status.fame = Math.min(100, st.status.fame + 1);
434	      StateManager.addMessage(
435	        "👕 买了一件衬衫！看起来人模人样的。卫生+10，名气+1。",
436	        "success",
437	      );
438	      consumeAP(20);
439	    },
440	  });
441	
442	  // === 投资 / 理财类 ===
443	  actions.push({
444	    id: "lottery",
445	    name: "🎰 买张彩票",
446	    desc: "花 2 块买注彩票，搏一搏单车变摩托。",
447	    icon: "🎰",
448	    costEstimate: 2,
449	    apCost: 20,
450	    payEstimate: "0或50万",
451	    handler: () => {
452	      const st = StateManager.getState();
453	      if (st.resources.cash < 2) {
454	        StateManager.addMessage("🎰 2 块都掏不出来。", "warning");
455	        return;
456	      }
457	      st.resources.cash -= 2;
458	      const roll = Math.random();
459	      if (roll < 0.0005) {
460	        st.resources.cash += 500000;
461	        st.resources.totalEarned += 500000;
462	        st.needs.happiness = Math.min(100, st.needs.happiness + 50);
463	        StateManager.addMessage(
464	          "🎰🎉🎉🎉 中了头奖！¥500,000 到账！财务自由就在眼前！",
465	          "success",
466	        );
467	      } else if (roll < 0.05) {
468	        const prize = 50 + Math.floor(Math.random() * 200);
469	        st.resources.cash += prize;
470	        st.resources.totalEarned += prize;
471	        st.needs.happiness = Math.min(100, st.needs.happiness + 15);
472	        StateManager.addMessage(`🎰 小赚一笔！中了 ¥${prize}！`, "success");
473	      } else {
474	        st.needs.happiness = Math.max(0, st.needs.happiness - 2);
475	        StateManager.addMessage("🎰 没中。", "info");
476	      }
477	      consumeAP(20);
478	    },
479	  });
480	
481	  actions.push({
482	    id: "yu_e_bao",
483	    name: "💰 买余额宝理财",
484	    desc: "把闲钱存进余额宝，每天 0.01% 收益。",
485	    icon: "💰",
486	    costEstimate: "100起",
487	    apCost: 20,
488	    payEstimate: "日息0.01%",
489	    handler: () => {
490	      showYuEBaoModal();
491	    },
492	  });
493	
494	  actions.push({
495	    id: "buy_insurance",
496	    name: "🛡️ 买保险",
497	    desc: "花 200 买份意外险，下次受伤/生病能赔 500。",
498	    icon: "🛡️",
499	    costEstimate: 200,
500	    handler: () => {
501	      const st = StateManager.getState();
502	      if (st.resources.cash < 200) {
503	        StateManager.addMessage("🛡️ 保险都买不起。", "warning");
504	        return;
505	      }
506	      st.resources.cash -= 200;
507	      st.flags.hasInsurance = true;
508	      st.flags.insuranceExpire = st.player.day + 30;
509	      StateManager.addMessage(
510	        "🛡️ 买了 30 天意外险！期间受伤/生病赔付 500。",
511	        "success",
512	      );
513	      consumeAP(20);
514	    },
515	  });
516	
517	  // === 梦想 / 自我实现类 ===
518	  actions.push({
519	    id: "diary",
520	    name: "📓 写日记",
521	    desc: "记录今天的心情。回顾一下，反思成长。",
522	    icon: "📓",
523	    handler: () => {
524	      const st = StateManager.getState();
525	      st.needs.happiness = Math.min(100, st.needs.happiness + 8);
526	      st.player.mental = Math.min(100, st.player.mental + 0.5);
527	      st.needs.fatigue = Math.max(0, st.needs.fatigue - 5);
