539	    desc: "在公园/家里静坐 15 分钟。恢复心智、缓解疲劳。",
540	    icon: "🧘",
541	    handler: () => {
542	      const st = StateManager.getState();
543	      st.player.mental = Math.min(100, st.player.mental + 1);
544	      st.needs.fatigue = Math.max(0, st.needs.fatigue - 12);
545	      st.needs.happiness = Math.min(100, st.needs.happiness + 6);
546	      StateManager.addMessage(
547	        "🧘 闭眼冥想了 15 分钟。内心平静，疲劳-12。",
