562	    disabled: state.skills.sales.level < 10 || state.resources.cash < 200,
563	    reqFail:
564	      state.skills.sales.level < 10
565	        ? "需销售≥10"
566	        : state.resources.cash < 200
567	          ? "现金不足"
568	          : null,
569	    handler: () => {
570	      const st = StateManager.getState();
571	      if (st.resources.cash < 200) {
572	        StateManager.addMessage("🏪 200 块启动资金都没有。", "warning");
573	        return;
574	      }
575	      st.resources.cash -= 200;
576	      st.needs.fatigue = Math.min(100, st.needs.fatigue + 25);
577	      const luck = Math.random();
578	      if (luck < 0.3) {
579	        // 大赚（现实：摆摊日赚100~350）
580	        const earned = 150 + Math.floor(Math.random() * 200);
581	        st.resources.cash += earned;
582	        st.resources.totalEarned += earned;
583	        st.skills.sales.xp += 20;
584	        st.status.fame = Math.min(100, st.status.fame + 2);
585	        StateManager.addMessage(
586	          `🏪 摆摊大成功！赚 ¥${earned}！销售经验++`,
587	          "success",
588	        );
589	      } else if (luck < 0.85) {
590	        // 小赚（现实：摆摊日赚30~120）
591	        const earned = 30 + Math.floor(Math.random() * 90);
592	        st.resources.cash += earned;
593	        st.resources.totalEarned += earned;
594	        st.skills.sales.xp += 10;
595	        StateManager.addMessage(`🏪 摆摊小赚 ¥${earned}。`, "success");
596	      } else {
597	        // 亏了
598	        StateManager.addMessage(
599	          "🏪 摆摊失败！货没卖掉，城管还罚了款。",
600	          "danger",
601	        );
602	        st.resources.cash = Math.max(0, st.resources.cash - 50);
603	        st.needs.happiness = Math.max(0, st.needs.happiness - 5);
604	      }
605	      consumeAP(20);
606	    },
607	  });
608	}
609	
610	/** 汇款模态框 */
611	function showRemitModal() {
612	  const state = StateManager.getState();
613	  showModal({
614	    title: "💌 给家里汇款",
615	    body: `<p>当前现金: ¥${state.resources.cash.toLocaleString()}</p>
616	           <p style="font-size:11px;color:var(--text-secondary);">每汇 100 元，心情+3，名气+0.5。</p>
617	           <label>汇款金额: <input id="remit-amount" type="number" min="100" max="${state.resources.cash}" value="200" style="width:100%;padding:8px;margin-top:8px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;"></label>`,
618	    buttons: [
619	      { text: "取消", cls: "", callback: () => {} },
620	      {
621	        text: "汇款",
622	        cls: "btn-primary",
623	        callback: () => {
624	          const amt = Math.max(
625	            0,
626	            Math.min(
627	              state.resources.cash,
628	              parseInt(document.getElementById("remit-amount")?.value || 0),
629	            ),
630	          );
631	          if (amt < 100) {
632	            StateManager.addMessage("💌 至少汇 100 块。", "warning");
633	            return;
634	          }
635	          state.resources.cash -= amt;
636	          state.needs.happiness = Math.min(
637	            100,
638	            state.needs.happiness + (amt / 100) * 3,
639	          );
640	          state.status.fame = Math.min(
641	            100,
642	            state.status.fame + (amt / 100) * 0.5,
643	          );
644	          StateManager.addMessage(
645	            `💌 给家里汇了 ¥${amt.toLocaleString()}，爸妈很高兴。`,
646	            "success",
647	          );
648	          document.querySelector(".modal-overlay")?.remove();
649	          renderAll();
650	        },
651	      },
652	    ],
653	  });
654	}
655	
