657	function showYuEBaoModal() {
658	  const state = StateManager.getState();
659	  const yue = state.flags.yuEBao || 0;
660	  const todayInterest = Math.floor(yue * 0.0001);
661	  showModal({
662	    title: "💰 余额宝理财",
663	    body: `
664	      <p>当前余额宝: <strong style="color:var(--success);">¥${yue.toLocaleString()}</strong></p>
665	      <p>今日收益预估: <strong>+¥${todayInterest}</strong>（日息 0.01%）</p>
666	      <p>现金: ¥${state.resources.cash.toLocaleString()}</p>
667	      <label>转入金额: <input id="yue-amount" type="number" min="100" max="${state.resources.cash}" value="${Math.floor(state.resources.cash)}" style="width:100%;padding:8px;margin-top:8px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;"></label>
668	    `,
669	    buttons: [
670	      { text: "取消", cls: "", callback: () => {} },
671	      {
672	        text: "全部转出",
673	        cls: "btn-warning",
674	        callback: () => {
675	          state.resources.cash += yue;
676	          state.flags.yuEBao = 0;
677	          StateManager.addMessage(
678	            `💰 从余额宝转出 ¥${yue.toLocaleString()}。`,
679	            "info",
680	          );
681	          document.querySelector(".modal-overlay")?.remove();
682	          renderAll();
683	        },
684	      },
685	      {
686	        text: "确认转入",
687	        cls: "btn-success",
688	        callback: () => {
689	          const amt = Math.max(
690	            0,
691	            Math.min(
692	              state.resources.cash,
693	              parseInt(document.getElementById("yue-amount")?.value || 0),
694	            ),
695	          );
696	          if (amt < 100) {
697	            StateManager.addMessage("💰 至少转入 100 块。", "warning");
698	            return;
699	          }
700	          state.resources.cash -= amt;
701	          state.flags.yuEBao = (state.flags.yuEBao || 0) + amt;
702	          StateManager.addMessage(
703	            `💰 转入余额宝 ¥${amt.toLocaleString()}。`,
704	            "success",
705	          );
706	          document.querySelector(".modal-overlay")?.remove();
707	          renderAll();
708	        },
709	      },
710	    ],
711	  });
712	}
713	
714	/** 给 main.js 调用的统一入口 */
715	function addExtraActions(state, actions) {
716	  if (state.player.phase === "street") {
717	    addStreetExtras(state, actions);
718	  }
719	  // 余额宝每日利息
720	  if (state.flags.yuEBao > 0) {
721	    const interest = Math.floor(state.flags.yuEBao * 0.0001);
722	    if (interest > 0) {
723	      state.flags.yuEBao += interest;
724	    }
725	  }
726	  // 保险检查
727	  if (
728	    state.flags.hasInsurance &&
729	    state.flags.insuranceExpire < state.player.day
730	  ) {
731	    state.flags.hasInsurance = false;
732	    StateManager.addMessage("🛡️ 你的保险到期了，记得续保。", "info");
733	  }
734	  if (state.flags.hasInsurance && (state.status.injured || state.status.sick)) {
735	    if (!state.flags._insurancePaidThisCycle) {
736	      state.resources.cash += 500;
737	      state.flags._insurancePaidThisCycle = true;
738	      StateManager.addMessage("🛡️ 保险赔付了 ¥500！", "success");
739	    }
740	  }
741	  if (!state.status.injured && !state.status.sick) {
742	    state.flags._insurancePaidThisCycle = false;
743	  }
744	}
