      maxAge: 60,
    },
    effects: { fatigue: 28, hygiene: -12, physiqueXp: 3, repairXp: 5 },
    payCalc(state) {
      return Math.floor(
        120 +
          state.skills.repair.level * 1.2 +
          state.player.physique * 0.25 +
