    },
    risk: { injury: 0.05 },
  },

  // ====== 工业区 — 工厂 ======
  {
    id: "factory_work_assembly",
    name: "工厂流水线",
    desc: "在电子厂做装配工。机械重复手不停，但收入稳定包吃住。",
    icon: "🏭",
    location: "factoryZone",
    requirements: { agility: 15, minAge: 18, maxAge: 45 },
    effects: {
      fatigue: 28,
      hygiene: -5,
      happiness: -15,
      mental: -2,
      agilityXp: 3,
    },
    payCalc(state) {
      return Math.floor(80 + state.player.agility * 0.3 + Math.random() * 18);
    },
    risk: { injury: 0.03, illness: 0.02 },
  },
  {
    id: "factory_overtime",
    name: "工厂加班",
    desc: "晚上加班赶订单，加班费可观，但这钱是用身体换的。",
    icon: "🌙",
    location: "factoryZone",
    requirements: { agility: 15, physique: 18, minAge: 18, maxAge: 45 },
    effects: { fatigue: 42, hygiene: -3, happiness: -20, mental: -4 },
    payCalc(state) {
      return Math.floor(115 + state.player.physique * 0.4 + Math.random() * 25);
    },
    risk: { illness: 0.06 },
  },

  // ====== 商业区 — 餐饮服务 ======
  {
