1	/**
2	 * 主渲染调度器
3	 *
4	 * 管理整个 UI 的渲染。使用脏标记 (dirty flag) 按需更新 DOM。
5	 * 渲染函数命名: render<Section>()
6	 */
7	
8	// 当前激活的 Tab
9	let currentTab = "actions";
10	
11	// ====== 紧凑型低数值预警 ======
12	/**
13	 * 为 stat-row 元素添加颜色匹配的紧凑预警
14	 * @param id - stat-row 的 DOM ID
15	 * @param value - 当前值
16	 * @param threshold - 低于此值触发预警（疲劳/风险等高即坏的值用 inverted=true）
17	 * @param warnColor - 预警边框和闪烁颜色（匹配该要素本身的颜色）
18	 * @param inverted - true 表示"高于阈值"触发预警（用于疲劳、风险）
19	 */
20	function warnStatRow(id, value, threshold, warnColor, inverted) {
21	  var row = document.getElementById(id);
22	  if (!row) return;
23	  var isBad = inverted ? value >= threshold : value <= threshold;
24	  if (isBad) {
25	    // 紧凑预警：薄左边框 + 极淡背景 + 无额外 padding
26	    row.style.cssText =
27	      "border-left:3px solid " +
28	      warnColor +
29	      ";" +
30	      "background:linear-gradient(90deg, " +
31	      warnColor +
32	      "15, transparent 40%);" +
33	      "padding-left:6px;margin:1px 0;border-radius:0 4px 4px 0;" +
34	      "transition:all 0.3s;";
35	    // 数值变色
36	    var valEl = row.querySelector(".stat-value");
37	    if (valEl) {
38	      valEl.style.color = warnColor;
39	      valEl.style.fontWeight = "bold";
40	      valEl.style.animation = "ap-blink 0.7s infinite";
41	    }
42	  } else {
43	    row.style.cssText = "";
44	    var valEl2 = row.querySelector(".stat-value");
45	    if (valEl2) {
46	      valEl2.style.color = "";
47	      valEl2.style.fontWeight = "";
48	      valEl2.style.animation = "";
49	    }
50	  }
51	}
52	
53	// ====== 主渲染入口 ======
54	function renderAll() {
55	  const state = StateManager.getState();
56	
57	  renderHeader(state);
58	  renderSidebar(state);
59	  renderTabBar(state);
60	  renderCurrentTab(state);
61	  renderMessageLog(state);
62	
63	  StateManager.cleanAllDirty();
64	}
65	
66	// ====== Header 渲染 ======
67	function renderHeader(state) {
68	  const p = state.player;
69	  const r = state.resources;
70	  const phaseLabel = p.phase === "corporate" ? "🏢 职场" : "🏘️ 街头";
71	
72	  document.getElementById("header-day").textContent = p.day;
73	  document.getElementById("header-age").textContent = p.age;
74	  document.getElementById("header-phase").textContent = phaseLabel;
75	  document.getElementById("header-cash").textContent =
76	    "¥" + r.cash.toLocaleString();
77	}
78	
79	// ====== Sidebar 渲染 ======
80	function renderSidebar(state) {
81	  const p = state.player;
82	
83	  if (p.phase === "street") {
84	    renderStreetStats(state);
85	  } else {
86	    renderCorporateStats(state);
87	  }
88	
89	  renderNeedsBars(state);
90	  renderLocation(state);
91	  renderDebtInfo(state);
92	}
93	
94	/** 侧边栏显示村长/银行债务 */
95	function renderDebtInfo(state) {
96	  const debtSection = document.getElementById("debt-section");
97	  if (!debtSection) return;
98	  const villageDebt = state.resources.villageDebt || state.resources.debt || 0;
99	  const villageInterest = state.resources.villageDebtInterest || 0;
100	  const bankDebt = state.resources.bankDebt || 0;
101	  let html = "";
102	  if (villageDebt > 0) {
103	    html += `<div style="padding:6px 10px;margin:2px 0;background:rgba(231,76,60,0.08);border-radius:4px;font-size:11px;">
104	      🏘️ 欠村长: <strong style="color:var(--danger);">¥${villageDebt.toLocaleString()}</strong>
105	      ${villageInterest > 0 ? ` <span style="color:var(--text-muted);">(利息+¥${villageInterest.toLocaleString()})</span>` : ""}
106	    </div>`;
107	  }
108	  if (bankDebt > 0) {
109	    html += `<div style="padding:6px 10px;margin:2px 0;background:rgba(243,156,18,0.08);border-radius:4px;font-size:11px;">
110	      🏦 欠银行: <strong style="color:var(--warning);">¥${bankDebt.toLocaleString()}</strong>
111	    </div>`;
112	  }
113	  debtSection.innerHTML = html;
114	  debtSection.style.display =
115	    villageDebt > 0 || bankDebt > 0 ? "block" : "none";
116	}
117	
118	function renderStreetStats(state) {
119	  const p = state.player;
120	  setStatBar("stat-physique", p.physique, "physique");
121	  setStatBar("stat-intelligence", p.intelligence, "intelligence");
122	  setStatBar("stat-agility", p.agility, "agility");
123	  setStatBar("stat-mental", p.mental, "mental-bar");
124	  // 低数值预警（基础属性阈值=10）
125	  warnStatRow("stat-physique", p.physique, 10, "#e67e22");
126	  warnStatRow("stat-intelligence", p.intelligence, 10, "#3498db");
127	  warnStatRow("stat-agility", p.agility, 10, "#2ecc71");
128	  warnStatRow("stat-mental", p.mental, 10, "#9b59b6");
129	}
