622	function createActionCard(action, state) {
623	  const card = document.createElement("div");
624	  card.className = "action-card";
625	  if (action.disabled) {
626	    card.classList.add("disabled");
627	  }
628	
629	  card.innerHTML = `
630	    <div class="card-icon">${action.icon}</div>
631	    <div class="card-title">${action.name}</div>
