// ====== 时间推进 (AP 行动力系统) ======

/** 消耗行动力，推进时间。每次行动调用此函数替代旧的 advanceTimeSlot() */
function consumeAP(cost) {
  const state = StateManager.getState();
  state.player.actionPoints = Math.max(0, state.player.actionPoints - cost);

  // 更新显示用的时段
  const pct = state.player.actionPoints / state.player.maxActionPoints;
  if (pct > 0.66) state.player.timeSlot = "morning";
  else if (pct > 0.33) state.player.timeSlot = "afternoon";
  else state.player.timeSlot = "evening";

  // Per-action 随机事件判定 (6%基础概率)
  if (!state._pendingEvent) {
    const phase = state.player.phase === "corporate" ? "corporate" : "street";
    if (Math.random() < 0.06) {
      if (typeof queueRandomEvent === "function")
        queueRandomEvent(state, phase);
    }
  }

  // 低行动力警告（≤20 且 > 0）
  if (state.player.actionPoints > 0 && state.player.actionPoints <= 20) {
    StateManager.addMessage(
      `⚠️ 仅剩 ${state.player.actionPoints} 点行动力！即将结束今天。`,
      "warning",
    );
  }

  // 行动力耗尽 → 结束一天
  if (state.player.actionPoints <= 0) {
    endDay();
  }
}

/** 旧API兼容别名 */
function advanceTimeSlot() {
  consumeAP(33); // 保持旧的3时段行为
}

function endDay() {
  const state = StateManager.getState();

  state.player.day++;
  // 重置行动力
  state.player.actionPoints = state.player.maxActionPoints;
  state.player.timeSlot = "morning";

  // 使用需求系统模块
  if (typeof applyNeedsDecay === "function") applyNeedsDecay(state);
  else {
    state.needs.hunger = Math.max(0, state.needs.hunger - 18);
    state.needs.hygiene = Math.max(0, state.needs.hygiene - 8);
  }
  // 睡眠恢复（基础25 + 住所加成）
  const house = getCurrentHousing(state);
  state.needs.fatigue = Math.max(
    0,
    state.needs.fatigue - house.fatigueRecovery,
  );
  state.needs.hygiene = Math.min(
    100,
    state.needs.hygiene + (house.hygieneBonus || 0),
