  1	/**
  2	 * 交易系统 — 买卖商品、价格波动、批发进货
  3	 *
  4	 * 提供: buyGood(), sellGood(), buyWholesale(), updatePrices()
  5	 */
  6	
  7	/** 玩家购买商品 */
  8	function buyGood(goodId, qty) {
  9	  const state = StateManager.getState();
 10	  const good = getGoodById(goodId);
 11	  if (!good) {
 12	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
 13	    return false;
 14	  }
 15	
 16	  const locKey = state.trade.currentLocation;
 17	  const price = getCurrentPrice(locKey, goodId);
 18	
 19	  // 销售技能折扣（最高15%）
 20	  const salesLvl = state.skills.sales.level || 0;
 21	  const discount = Math.min(0.15, salesLvl * 0.002);
 22	  const totalCost = Math.round(price * qty * (1 - discount) * 100) / 100;
 23	
 24	  // 检查现金
 25	  if (state.resources.cash < totalCost) {
 26	    StateManager.addMessage(
 27	      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}，你只有 ¥${state.resources.cash}。`,
 28	      "danger",
 29	    );
 30	    return false;
 31	  }
 32	
 33	  // 检查背包容量
 34	  const currentItems = state.inventory.items.reduce(
 35	    (sum, item) => sum + item.qty,
 36	    0,
 37	  );
 38	  if (currentItems + qty > state.inventory.capacity) {
 39	    StateManager.addMessage(
 40	      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
 41	      "danger",
 42	    );
 43	    return false;
 44	  }
 45	
 46	  // 扣钱
 47	  state.resources.cash -= totalCost;
 48	
 49	  // 加入背包
 50	  const existing = state.inventory.items.find((i) => i.id === goodId);
 51	  if (existing) {
 52	    existing.qty += qty;
 53	    existing.boughtAt = locKey;
 54	  } else {
 55	    state.inventory.items.push({ id: goodId, qty, boughtAt: locKey });
 56	  }
 57	
 58	  // 买入后该商品在当地涨价 0.5~1.5%（原1~3%，缩小波动）
 59	  const buyDelta = 0.005 + Math.random() * 0.01;
 60	  adjustPriceAfterTrade(locKey, goodId, buyDelta);
 61	  const newPrice = getCurrentPrice(locKey, goodId);
 62	
 63	  StateManager.addMessage(
 64	    `🛒 购买了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalCost.toFixed(1)}。${newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : ""}`,
 65	    "success",
 66	  );
 67	  return true;
 68	}
 69	
 70	/** 玩家卖出商品 */
 71	function sellGood(goodId, qty) {
 72	  const state = StateManager.getState();
 73	  const good = getGoodById(goodId);
 74	  if (!good) {
 75	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
 76	    return false;
 77	  }
 78	
 79	  // 检查背包
 80	  const existing = state.inventory.items.find((i) => i.id === goodId);
 81	  if (!existing || existing.qty < qty) {
 82	    StateManager.addMessage(`⚠️ 背包中没有足够的${good.name}！`, "danger");
 83	    return false;
 84	  }
 85	
 86	  const locKey = state.trade.currentLocation;
 87	  let price = getCurrentPrice(locKey, goodId);
 88	
 89	  // 同地转卖惩罚：如果卖出地点就是购买地点，售价打4.5折（现实：原地倒卖几乎必亏）
 90	  let sameLocationPenalty = false;
 91	  if (existing.boughtAt === locKey) {
 92	    price = Math.round(price * 0.4 * 100) / 100;
 93	    sameLocationPenalty = true;
 94	  }
 95	
 96	  // 销售技能溢价（最高15%）
 97	  const salesLvl = state.skills.sales.level || 0;
 98	  const premium = Math.min(0.15, salesLvl * 0.002);
 99	  const totalEarned =
100	    Math.round(price * qty * (1 + premium) * 0.95 * 100) / 100;
101	
102	  // 加钱
103	  state.resources.cash += totalEarned;
104	  state.resources.totalEarned += totalEarned;
105	  // 追踪累计交易利润
106	  const avgBuy = getAvgBuyPrice(state, goodId);
107	  if (avgBuy > 0) {
108	    const unitProfit = totalEarned / qty - avgBuy;
109	    if (unitProfit > 0) {
110	      state.trade.totalProfit =
111	        (state.trade.totalProfit || 0) + unitProfit * qty;
112	    }
113	  }
114	
115	  // 从背包移除
116	  existing.qty -= qty;
117	  if (existing.qty <= 0) {
118	    state.inventory.items = state.inventory.items.filter(
119	      (i) => i.id !== goodId,
120	    );
121	  }
122	
123	  // 低买高卖时显示利润
124	  const buyPrice = getAvgBuyPrice(state, goodId); // 估算买入价
125	  let profitMsg = "";
126	  if (sameLocationPenalty) {
127	    profitMsg = " ⚠️ 同地转卖，贬值严重！";
128	  } else if (buyPrice > 0) {
129	    const profit = totalEarned - buyPrice * qty;
130	    if (profit > 0) {
131	      profitMsg = ` 📈 获利 ¥${profit.toFixed(1)}！`;
132	    } else if (profit < 0) {
133	      profitMsg = ` 📉 亏损 ¥${Math.abs(profit).toFixed(1)}。`;
134	    }
135	  }
136	
137	  // 卖出后该商品在当地降价 0.5~1.5%（原1~3%，缩小波动）
138	  const sellDelta = -(0.005 + Math.random() * 0.01);
139	  adjustPriceAfterTrade(locKey, goodId, sellDelta);
140	  const newPrice = getCurrentPrice(locKey, goodId);
141	  const priceMsg =
142	    newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : "";
143	
144	  StateManager.addMessage(
145	    `💰 卖出了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalEarned.toFixed(1)}。${profitMsg}${priceMsg}`,
146	    "success",
147	  );
148	  return true;
149	}
150	
151	/** 批发进货（批发市场专属） */
152	function buyWholesale(goodId, qty) {
153	  const state = StateManager.getState();
154	  const good = getGoodById(goodId);
155	  if (!good) {
156	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
157	    return false;
158	  }
159	
160	  const locKey = state.trade.currentLocation;
161	  const price = getCurrentPrice(locKey, goodId);
162	
163	  // 批发折扣：批发市场的价格 × 0.9（批量价，现实批发仅10%折扣）
164	  const wholesalePrice = Math.round(price * 0.95 * 100) / 100;
165	  const totalCost = Math.round(wholesalePrice * qty * 100) / 100;
166	
167	  // 最低起批量
168	  if (qty < 5) {
169	    StateManager.addMessage("⚠️ 批发最少购买5件。", "warning");
170	    return false;
171	  }
172	
173	  // 检查现金
174	  if (state.resources.cash < totalCost) {
175	    StateManager.addMessage(
176	      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}。`,
177	      "danger",
178	    );
179	    return false;
180	  }
181	
182	  // 检查背包
183	  const currentItems = state.inventory.items.reduce(
184	    (sum, item) => sum + item.qty,
185	    0,
186	  );
187	  if (currentItems + qty > state.inventory.capacity) {
188	    StateManager.addMessage(
189	      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
190	      "danger",
191	    );
192	    return false;
193	  }
194	
195	  // 扣钱
196	  state.resources.cash -= totalCost;
197	
198	  // 记录买入价（用于后续利润计算）
199	  const existing = state.inventory.items.find((i) => i.id === goodId);
200	  if (existing) {
201	    // 加权平均买入价
202	    const oldTotal = (existing.avgBuyPrice || wholesalePrice) * existing.qty;
203	    const newTotal = wholesalePrice * qty;
204	    existing.qty += qty;
205	    existing.boughtAt = locKey;
206	    existing.avgBuyPrice =
207	      Math.round(((oldTotal + newTotal) / existing.qty) * 100) / 100;
208	  } else {
209	    state.inventory.items.push({
210	      id: goodId,
211	      qty,
212	      avgBuyPrice: wholesalePrice,
213	      boughtAt: locKey,
214	    });
215	  }
216	
217	  StateManager.addMessage(
218	    `📦 批发进货 ${qty}${good.unit}${good.name}，批发价 ¥${wholesalePrice.toFixed(1)}/件，共 ¥${totalCost.toFixed(1)}。`,
219	    "success",
220	  );
221	  return true;
222	}
223	
224	/** 快速出售（从背包里选一个商品卖） */
225	function quickSell(goodId) {
226	  const state = StateManager.getState();
227	  const existing = state.inventory.items.find((i) => i.id === goodId);
228	  if (!existing || existing.qty <= 0) {
229	    StateManager.addMessage(`⚠️ 背包中没有该商品。`, "warning");
230	    return false;
231	  }
232	  const qty = Math.min(existing.qty, 1); // 默认卖1个
233	  return sellGood(goodId, qty);
234	}
235	
236	/** 交易后动态调价：买入涨价，卖出降价 */
237	function adjustPriceAfterTrade(locKey, goodId, delta) {
238	  const state = StateManager.getState();
239	  const good = getGoodById(goodId);
240	  if (!good) return;
241	  const prices = state.trade.goodsPrices[locKey];
242	  if (!prices) return;
243	  const oldPrice = prices[goodId] || good.basePrice;
244	  const change = oldPrice * delta;
245	  let newPrice = oldPrice + change;
246	  // 限制范围
247	  newPrice = Math.max(
248	    good.basePrice * 0.3,
249	    Math.min(good.basePrice * 5, newPrice),
250	  );
251	  newPrice = Math.round(newPrice * 100) / 100;
252	  prices[goodId] = newPrice;
253	}
254	
255	/** 获取当前地点某商品的零售价 */
256	function getCurrentPrice(locKey, goodId) {
257	  const state = StateManager.getState();
258	  const prices = state.trade.goodsPrices[locKey];
259	  if (prices && prices[goodId] !== undefined) {
260	    return prices[goodId];
261	  }
262	  const good = getGoodById(goodId);
263	  return good ? good.basePrice : 1;
264	}
265	
266	/** 获取某商品在所有地点的最低价格（用于价格对比） */
267	function getLowestPrice(goodId) {
268	  const state = StateManager.getState();
269	  let lowest = Infinity;
270	  let lowestLoc = null;
271	  for (const locKey of Object.keys(LOCATIONS)) {
272	    const prices = state.trade.goodsPrices[locKey] || {};
273	    const price = prices[goodId];
274	    if (price && price < lowest) {
275	      lowest = price;
276	      lowestLoc = locKey;
277	    }
278	  }
279	  return { price: lowest, location: lowestLoc };
280	}
281	
282	/** 获取某商品在所有地点的最高价格 */
283	function getHighestPrice(goodId) {
284	  const state = StateManager.getState();
285	  let highest = 0;
286	  let highestLoc = null;
287	  for (const locKey of Object.keys(LOCATIONS)) {
288	    const prices = state.trade.goodsPrices[locKey] || {};
289	    const price = prices[goodId];
290	    if (price && price > highest) {
291	      highest = price;
292	      highestLoc = locKey;
293	    }
294	  }
295	  return { price: highest, location: highestLoc };
296	}
297	
298	/** 估算平均买入价 */
299	function getAvgBuyPrice(state, goodId) {
300	  const item = state.inventory.items.find((i) => i.id === goodId);
301	  return item ? item.avgBuyPrice || 0 : 0;
302	}
303	
304	/** 更新所有地点所有商品的价格（每3天调用一次） */
305	function updateAllPrices(state) {
306	  for (const locKey of Object.keys(LOCATIONS)) {
307	    const loc = LOCATIONS[locKey];
308	    // 确保价格对象存在
309	    if (!state.trade.goodsPrices[locKey]) {
310	      state.trade.goodsPrices[locKey] = {};
311	    }
312	    for (const good of GOODS) {
313	      let price = good.basePrice;
314	
315	      // 1. 地点倍率
316	      if (loc.priceMod && loc.priceMod[good.id]) {
317	        price *= loc.priceMod[good.id];
318	      }
319	
320	      // 2. 随机波动 ±12%（原 ±15%，现实级差价）
321	      const fluctuation = 0.92 + Math.random() * 0.16;
322	      price *= fluctuation;
323	
324	      // 3. 均值回归（10%向旧价格靠拢）
325	      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
326	      price = price + (oldPrice - price) * 0.1;
327	
328	      // 4. 限制在合理范围（现实级差价空间：0.5x~3x）
329	      price = Math.max(
330	        good.basePrice * 0.5,
331	        Math.min(good.basePrice * 2, price),
332	      );
333	      price = Math.round(price * 100) / 100;
334	
335	      state.trade.goodsPrices[locKey][good.id] = price;
336	    }
337	  }
338	  state.trade.lastPriceUpdate = state.player.day;
339	}

