 70	/** 玩家卖出商品 */
 71	function sellGood(goodId, qty) {
 72	  const state = StateManager.getState();
 73	  const good = getGoodById(goodId);
 74	  if (!good) {
 75	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
 76	    return false;
 77	  }
 78	
 79	  // 检查背包
 80	  const existing = state.inventory.items.find((i) => i.id === goodId);
 81	  if (!existing || existing.qty < qty) {
 82	    StateManager.addMessage(`⚠️ 背包中没有足够的${good.name}！`, "danger");
 83	    return false;
 84	  }
 85	
 86	  const locKey = state.trade.currentLocation;
 87	  let price = getCurrentPrice(locKey, goodId);
 88	
 89	  // 同地转卖惩罚：如果卖出地点就是购买地点，售价打4.5折（现实：原地倒卖几乎必亏）
 90	  let sameLocationPenalty = false;
 91	  if (existing.boughtAt === locKey) {
 92	    price = Math.round(price * 0.4 * 100) / 100;
 93	    sameLocationPenalty = true;
 94	  }
 95	
 96	  // 销售技能溢价（最高15%）
 97	  const salesLvl = state.skills.sales.level || 0;
 98	  const premium = Math.min(0.15, salesLvl * 0.002);
 99	  const totalEarned =
100	    Math.round(price * qty * (1 + premium) * 0.95 * 100) / 100;
101	
102	  // 加钱
103	  state.resources.cash += totalEarned;
104	  state.resources.totalEarned += totalEarned;
105	  // 追踪累计交易利润
106	  const avgBuy = getAvgBuyPrice(state, goodId);
107	  if (avgBuy > 0) {
108	    const unitProfit = totalEarned / qty - avgBuy;
109	    if (unitProfit > 0) {
110	      state.trade.totalProfit =
111	        (state.trade.totalProfit || 0) + unitProfit * qty;
112	    }
113	  }
114	
115	  // 从背包移除
116	  existing.qty -= qty;
117	  if (existing.qty <= 0) {
118	    state.inventory.items = state.inventory.items.filter(
119	      (i) => i.id !== goodId,
120	    );
121	  }
122	
123	  // 低买高卖时显示利润
124	  const buyPrice = getAvgBuyPrice(state, goodId); // 估算买入价
125	  let profitMsg = "";
126	  if (sameLocationPenalty) {
127	    profitMsg = " ⚠️ 同地转卖，贬值严重！";
128	  } else if (buyPrice > 0) {
129	    const profit = totalEarned - buyPrice * qty;
130	    if (profit > 0) {
131	      profitMsg = ` 📈 获利 ¥${profit.toFixed(1)}！`;
132	    } else if (profit < 0) {
133	      profitMsg = ` 📉 亏损 ¥${Math.abs(profit).toFixed(1)}。`;
134	    }
135	  }
136	
137	  // 卖出后该商品在当地降价 0.5~1.5%（原1~3%，缩小波动）
138	  const sellDelta = -(0.005 + Math.random() * 0.01);
139	  adjustPriceAfterTrade(locKey, goodId, sellDelta);
140	  const newPrice = getCurrentPrice(locKey, goodId);
141	  const priceMsg =
142	    newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : "";
143	
144	  StateManager.addMessage(
145	    `💰 卖出了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalEarned.toFixed(1)}。${profitMsg}${priceMsg}`,
146	    "success",
147	  );
148	  return true;
149	}
