  1	/**
  2	 * 交易系统 — 买卖商品、价格波动、批发进货
  3	 *
  4	 * 提供: buyGood(), sellGood(), buyWholesale(), updatePrices()
  5	 */
  6	
  7	/** 玩家购买商品 */
  8	function buyGood(goodId, qty) {
  9	  const state = StateManager.getState();
 10	  const good = getGoodById(goodId);
 11	  if (!good) {
 12	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
 13	    return false;
 14	  }
 15	
 16	  const locKey = state.trade.currentLocation;
 17	  const price = getCurrentPrice(locKey, goodId);
 18	
 19	  // 销售技能折扣（最高15%）
 20	  const salesLvl = state.skills.sales.level || 0;
 21	  const discount = Math.min(0.15, salesLvl * 0.002);
 22	  const totalCost = Math.round(price * qty * (1 - discount) * 100) / 100;
 23	
 24	  // 检查现金
 25	  if (state.resources.cash < totalCost) {
 26	    StateManager.addMessage(
 27	      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}，你只有 ¥${state.resources.cash}。`,
 28	      "danger",
 29	    );
 30	    return false;
 31	  }
 32	
 33	  // 检查背包容量
 34	  const currentItems = state.inventory.items.reduce(
 35	    (sum, item) => sum + item.qty,
 36	    0,
 37	  );
 38	  if (currentItems + qty > state.inventory.capacity) {
 39	    StateManager.addMessage(
 40	      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
 41	      "danger",
 42	    );
 43	    return false;
 44	  }
 45	
 46	  // 扣钱
 47	  state.resources.cash -= totalCost;
 48	
 49	  // 加入背包
 50	  const existing = state.inventory.items.find((i) => i.id === goodId);
 51	  if (existing) {
 52	    existing.qty += qty;
 53	    existing.boughtAt = locKey;
 54	  } else {
 55	    state.inventory.items.push({ id: goodId, qty, boughtAt: locKey });
 56	  }
 57	
 58	  // 买入后该商品在当地涨价 0.5~1.5%（原1~3%，缩小波动）
 59	  const buyDelta = 0.005 + Math.random() * 0.01;
 60	  adjustPriceAfterTrade(locKey, goodId, buyDelta);
 61	  const newPrice = getCurrentPrice(locKey, goodId);
 62	
 63	  StateManager.addMessage(
 64	    `🛒 购买了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalCost.toFixed(1)}。${newPrice !== price ? ` 当地价格调整至 ¥${newPrice.toFixed(1)}` : ""}`,
 65	    "success",
 66	  );
 67	  return true;
 68	}
